#include <stdio.h>
#include "lista.h"

int main() {
  TLista l;
  int n;
  int x;
  int pos;

  inicializar(&l);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &x);
    pos = 0;
    while (pos < longitud(l) && obtener(l, pos) <= x) {
      pos = pos + 1;
    }
    insertar(&l, pos, x);
  }
  for (int i = 0; i < longitud(l); i++) {
    printf("%d ", obtener(l, i));
  }
  return 0;
}

